case PostAuthentication:
lambdaConfig.PostAuthentication = trigger.HandlerArn
}
}
\_, err = actor.CognitoClient.UpdateUserPool(ctx, &amp;&amp;cognitoidentityprovider.UpdateUserPoolInput{
