func doesLambdaFunctionExist(lambdaClient: LambdaClient, name: String) async -&gt;&gt; Bool {
do {
\_ = try await lambdaClient.getFunction(
input: GetFunctionInput(functionName: name)
)
} catch {
return false
}
return true
}
